     1→'use client';
     2→
     3→import { Badge } from '@tpmjs/ui/Badge/Badge';
     4→import { Button } from '@tpmjs/ui/Button/Button';
     5→import { Icon } from '@tpmjs/ui/Icon/Icon';
     6→import { Input } from '@tpmjs/ui/Input/Input';
     7→import { useCallback, useEffect, useRef, useState } from 'react';
     8→
     9→interface Tool {
    10→  id: string;
    11→  name: string;
    12→  description: string;
    13→  package: {
    14→    npmPackageName: string;
    15→    category: string;
    16→  };
    17→}
    18→
    19→interface AddToolSearchProps {
    20→  collectionId: string;
    21→  existingToolIds: string[];
    22→  onToolAdded: (tool: Tool) => void;
    23→}
    24→
    25→interface SearchResult {
    26→  id: string;
    27→  name: string;
    28→  description: string;
    29→  package: {
    30→    npmPackageName: string;
    31→    category: string;
    32→  };
    33→}
    34→
    35→export function AddToolSearch({
    36→  collectionId,
    37→  existingToolIds,
    38→  onToolAdded,
    39→}: AddToolSearchProps): React.ReactElement {
    40→  const [query, setQuery] = useState('');
    41→  const [results, setResults] = useState<SearchResult[]>([]);
    42→  const [isSearching, setIsSearching] = useState(false);
    43→  const [isOpen, setIsOpen] = useState(false);
    44→  const [addingId, setAddingId] = useState<string | null>(null);
    45→  const [error, setError] = useState<string | null>(null);
    46→  const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    47→  const containerRef = useRef<HTMLDivElement>(null);
    48→
    49→  // Debounced search
    50→  const search = useCallback(
    51→    async (searchQuery: string) => {
    52→      if (!searchQuery.trim()) {
    53→        setResults([]);
    54→        setIsOpen(false);
    55→        return;
    56→      }
    57→
    58→      setIsSearching(true);
    59→      setError(null);
    60→
    61→      try {
    62→        // Build URL with excludeIds to avoid returning tools already in collection
    63→        const params = new URLSearchParams({
    64→          q: searchQuery,
    65→          limit: '50', // Higher limit to handle large packages like @tpmjs/tools-unsandbox (59 tools)
    66→        });
    67→        // Pass existing tool IDs so server can exclude them
    68→        if (existingToolIds.length > 0) {
    69→          params.set('excludeIds', existingToolIds.join(','));
    70→        }
    71→        const response = await fetch(`/api/tools/search?${params.toString()}`);
    72→        const data = await response.json();
    73→
    74→        if (data.success && data.results?.tools) {
    75→          setResults(data.results.tools);
    76→          setIsOpen(true);
    77→        } else {
    78→          setResults([]);
    79→        }
    80→      } catch (err) {
    81→        console.error('Search failed:', err);
    82→        setError('Search failed');
    83→        setResults([]);
    84→      } finally {
    85→        setIsSearching(false);
    86→      }
    87→    },
    88→    [existingToolIds]
    89→  );
    90→
    91→  // Handle query changes with debounce
    92→  useEffect(() => {
    93→    if (searchTimeoutRef.current) {
    94→      clearTimeout(searchTimeoutRef.current);
    95→    }
    96→
    97→    if (query.trim()) {
    98→      searchTimeoutRef.current = setTimeout(() => {
    99→        search(query);
   100→      }, 300);
   101→    } else {
   102→      setResults([]);
   103→      setIsOpen(false);
   104→    }
   105→
   106→    return () => {
   107→      if (searchTimeoutRef.current) {
   108→        clearTimeout(searchTimeoutRef.current);
   109→      }
   110→    };
   111→  }, [query, search]);
   112→
   113→  // Close dropdown when clicking outside
   114→  useEffect(() => {
   115→    const handleClickOutside = (event: MouseEvent) => {
   116→      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
   117→        setIsOpen(false);
   118→      }
   119→    };
   120→
   121→    document.addEventListener('mousedown', handleClickOutside);
   122→    return () => document.removeEventListener('mousedown', handleClickOutside);
   123→  }, []);
   124→
   125→  const handleAddTool = async (tool: SearchResult) => {
   126→    setAddingId(tool.id);
   127→    setError(null);
   128→
   129→    try {
   130→      const response = await fetch(`/api/collections/${collectionId}/tools`, {
   131→        method: 'POST',
   132→        headers: { 'Content-Type': 'application/json' },
   133→        body: JSON.stringify({ toolId: tool.id }),
   134→      });
   135→
   136→      const data = await response.json();
   137→
   138→      if (data.success) {
   139→        onToolAdded({
   140→          id: tool.id,
   141→          name: tool.name,
   142→          description: tool.description,
   143→          package: tool.package,
   144→        });
   145→        // Remove the added tool from results but keep dropdown open for adding more
   146→        const remainingResults = results.filter((t) => t.id !== tool.id);
   147→        setResults(remainingResults);
   148→        // Close dropdown only if no more tools to add
   149→        if (remainingResults.length === 0) {
   150→          setIsOpen(false);
   151→          setQuery('');
   152→        }
   153→      } else {
   154→        setError(data.error?.message || 'Failed to add tool');
   155→      }
   156→    } catch (err) {
   157→      console.error('Failed to add tool:', err);
   158→      setError('Failed to add tool');
   159→    } finally {
   160→      setAddingId(null);
   161→    }
   162→  };
   163→
   164→  // Filter out already added tools
   165→  const filteredResults = results.filter((tool) => !existingToolIds.includes(tool.id));
   166→
   167→  return (
   168→    <div ref={containerRef} className="relative">
   169→      <div className="relative">
   170→        <Icon
   171→          icon="search"
   172→          size="sm"
   173→          className="absolute left-3 top-1/2 -translate-y-1/2 text-foreground-tertiary"
   174→        />
   175→        <Input
   176→          value={query}
   177→          onChange={(e) => setQuery(e.target.value)}
   178→          placeholder="Search for tools to add..."
   179→          className="pl-9"
   180→          onFocus={() => {
   181→            if (filteredResults.length > 0) {
   182→              setIsOpen(true);
   183→            }
   184→          }}
   185→        />
   186→        {isSearching && (
   187→          <Icon
   188→            icon="loader"
   189→            size="sm"
   190→            className="absolute right-3 top-1/2 -translate-y-1/2 text-foreground-tertiary animate-spin"
   191→          />
   192→        )}
   193→      </div>
   194→
   195→      {error && <p className="text-sm text-error mt-2">{error}</p>}
   196→
   197→      {isOpen && filteredResults.length > 0 && (
   198→        <div className="absolute z-50 w-full mt-2 bg-background border border-border rounded-lg shadow-lg max-h-80 overflow-y-auto">
   199→          {filteredResults.map((tool) => (
   200→            <div
   201→              key={tool.id}
   202→              className="p-3 hover:bg-surface-secondary transition-colors border-b border-border last:border-b-0"
   203→            >
   204→              <div className="flex items-start justify-between gap-3">
   205→                <div className="flex-1 min-w-0">
   206→                  <div className="flex items-center gap-2 mb-1">
   207→                    <span className="font-medium text-foreground truncate">{tool.name}</span>
   208→                    <Badge variant="secondary" size="sm">
   209→                      {tool.package.category}
   210→                    </Badge>
   211→                  </div>
   212→                  <p className="text-sm text-foreground-secondary line-clamp-2">
   213→                    {tool.description}
   214→                  </p>
   215→                  <p className="text-xs text-foreground-tertiary mt-1">
   216→                    {tool.package.npmPackageName}
   217→                  </p>
   218→                </div>
   219→                <Button
   220→                  size="sm"
   221→                  onClick={() => handleAddTool(tool)}
   222→                  loading={addingId === tool.id}
   223→                  disabled={addingId !== null}
   224→                >
   225→                  <Icon icon="plus" size="sm" className="mr-1" />
   226→                  Add
   227→                </Button>
   228→              </div>
   229→            </div>
   230→          ))}
   231→        </div>
   232→      )}
   233→
   234→      {isOpen && query.trim() && filteredResults.length === 0 && !isSearching && (
   235→        <div className="absolute z-50 w-full mt-2 bg-background border border-border rounded-lg shadow-lg p-4 text-center">
   236→          <p className="text-foreground-secondary">
   237→            {results.length > 0
   238→              ? 'All matching tools are already in this collection'
   239→              : 'No tools found matching your search'}
   240→          </p>
   241→        </div>
   242→      )}
   243→    </div>
   244→  );
   245→}
