   121→interface ToolsCallParams {
   122→  name: string;
   123→  arguments?: Record<string, unknown>;
   124→  env?: Record<string, string>; // Caller-provided env vars for non-owners
   125→}
   126→
   127→/**
   128→ * Handle MCP tools/call request
   129→ * @param callerEnvVars - Optional env vars from caller (non-owner accessing public collection)
   130→ *                        When provided, these are used INSTEAD of collection's stored env vars
   131→ */
   132→export async function handleToolsCall(
   133→  collectionId: string,
   134→  params: ToolsCallParams,
   135→  requestId: JsonRpcId,
   136→  callerEnvVars?: Record<string, string>
   137→): Promise<JsonRpcResponse> {
   138→  try {
   139→    const parsed = parseToolName(params.name);
   140→    if (!parsed) {
   141→      return {
   142→        jsonrpc: '2.0',
   143→        id: requestId,
   144→        error: { code: -32602, message: `Invalid tool name: ${params.name}` },
   145→      };
   146→    }
   147→
   148→    // Handle bridge tool calls
   149→    if (parsed.type === 'bridge') {
   150→      return handleBridgeToolCall(
   151→        collectionId,
   152→        parsed.serverId,
   153→        parsed.toolName,
   154→        params.arguments ?? {},
   155→        requestId
   156→      );
   157→    }
   158→
   159→    // Handle registry tool calls
   160→    // Verify tool exists in collection and get executor config
   161→    const collection = await withTimeout(
   162→      prisma.collection.findUnique({
   163→        where: { id: collectionId },
   164→        select: {
   165→          executorType: true,
   166→          executorConfig: true,
   167→          envVars: true,
   168→          tools: {
   169→            include: { tool: { include: { package: true } } },
   170→          },
   171→        },
   172→      }),
   173→      DB_TIMEOUT_MS,
   174→      'Database query timed out'
   175→    );
   176→
   177→    // Try all possible package name and tool name combinations
   178→    // This handles both old format (full package name) and new shortened format
   179→    type CollectionTool = NonNullable<typeof collection>['tools'][number];
   180→    let collectionTool: CollectionTool | undefined;
   181→
   182→    for (const pkgName of parsed.possiblePackages) {
   183→      for (const toolName of parsed.possibleToolNames) {
   184→        collectionTool = collection?.tools.find(
   185→          (ct) => ct.tool.package.npmPackageName === pkgName && ct.tool.name === toolName
   186→        );
   187→        if (collectionTool) break;
   188→      }
   189→      if (collectionTool) break;
   190→    }
   191→
   192→    if (!collectionTool) {
   193→      return {
   194→        jsonrpc: '2.0',
   195→        id: requestId,
   196→        error: { code: -32602, message: `Tool not found in collection: ${params.name}` },
   197→      };
   198→    }
   199→
   200→    // Get the actual package name and version that matched
   201→    const actualPackageName = collectionTool.tool.package.npmPackageName;
   202→    const actualVersion = collectionTool.tool.package.npmVersion;
   203→
   204→    // When caller provides env vars (non-owner), validate required env vars
   205→    if (callerEnvVars !== undefined) {
   206→      const packageEnv = collectionTool.tool.package.env as TpmjsEnv[] | null;
   207→      if (packageEnv && Array.isArray(packageEnv)) {
   208→        const missingVars = packageEnv.filter(
   209→          (env) => env.required !== false && !env.default && !callerEnvVars[env.name]
   210→        );
   211→
   212→        if (missingVars.length > 0) {
   213→          return {
   214→            jsonrpc: '2.0',
   215→            id: requestId,
   216→            error: {
   217→              code: -32602,
   218→              message: 'Missing required environment variables',
   219→              data: {
   220→                missingVars: missingVars.map((e) => ({
   221→                  name: e.name,
   222→                  description: e.description,
   223→                })),
   224→              },
   225→            },
   226→          };
   227→        }
   228→      }
   229→    }
   230→
   231→    // Resolve executor configuration (collection config only for MCP - no agent context)
   232→    const executorConfig = parseExecutorConfig(
   233→      collection?.executorType,
   234→      collection?.executorConfig
   235→    );
   236→
   237→    // Execute via resolved executor
   238→    // Use caller-provided env vars if given (non-owner), otherwise use collection's stored env vars
   239→    const effectiveEnvVars = callerEnvVars ?? (collection?.envVars as Record<string, string>) ?? {};
   240→    // Pass explicit version to avoid Deno HTTP import cache issues with @latest
   241→    // Use actual tool name from DB, not parsed name (which may have wrong suffix)
   242→    const result = await executeWithExecutor(executorConfig, {
   243→      packageName: actualPackageName,
   244→      name: collectionTool.tool.name,
   245→      version: actualVersion,
   246→      params: params.arguments ?? {},
   247→      env: Object.keys(effectiveEnvVars).length > 0 ? effectiveEnvVars : undefined,
   248→    });
   249→
   250→    if (!result.success) {
   251→      return {
   252→        jsonrpc: '2.0',
   253→        id: requestId,
   254→        result: {
   255→          content: [{ type: 'text', text: `Error: ${result.error}` }],
   256→          isError: true,
   257→        },
   258→      };
   259→    }
   260→
   261→    return {
   262→      jsonrpc: '2.0',
   263→      id: requestId,
   264→      result: {
   265→        content: [
   266→          {
   267→            type: 'text',
   268→            text:
   269→              typeof result.output === 'string'
   270→                ? result.output
   271→                : JSON.stringify(result.output, null, 2),
   272→          },
   273→        ],
   274→      },
   275→    };
   276→  } catch (error) {
   277→    console.error('[MCP tools/call] Error:', error);
   278→    return {
   279→      jsonrpc: '2.0',
   280→      id: requestId,
   281→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
   282→    };
   283→  }
   284→}
