    37→function withTimeout<T>(promise: Promise<T>, ms: number, errorMessage: string): Promise<T> {
    38→  return Promise.race([
    39→    promise,
    40→    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(errorMessage)), ms)),
    41→  ]);
    42→}
