    87→async function processJsonRpcRequest(
    88→  collectionId: string,
    89→  collectionName: string,
    90→  body: JsonRpcRequest,
    91→  isOwner: boolean
    92→): Promise<JsonRpcResponse> {
    93→  const requestId = body.id ?? null;
    94→
    95→  switch (body.method) {
    96→    case 'initialize':
    97→      return handleInitialize(collectionName, requestId);
    98→
    99→    case 'tools/list':
   100→      return await handleToolsList(collectionId, requestId);
   101→
   102→    case 'tools/call': {
   103→      const params = body.params as {
   104→        name: string;
   105→        arguments?: Record<string, unknown>;
   106→        env?: Record<string, string>;
   107→      };
   108→
   109→      // For non-owners, use caller-provided env vars (or empty if not provided)
   110→      // For owners, callerEnvVars is undefined so handleToolsCall uses stored env vars
   111→      const callerEnvVars = isOwner ? undefined : params.env || {};
   112→
   113→      return await handleToolsCall(collectionId, params, requestId, callerEnvVars);
   114→    }
   115→
   116→    case 'notifications/initialized':
   117→    case 'ping':
   118→      return { jsonrpc: '2.0', id: requestId, result: {} };
   119→
   120→    default:
   121→      return {
   122→        jsonrpc: '2.0',
   123→        id: requestId,
   124→        error: { code: -32601, message: `Method not found: ${body.method}` },
   125→      };
   126→  }
   127→}
