    41→function withTimeout<T>(promise: Promise<T>, ms: number, errorMessage: string): Promise<T> {
    42→  return Promise.race([
    43→    promise,
    44→    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(errorMessage)), ms)),
    45→  ]);
    46→}
