   384→          // Stream the response with agentic loop control
   385→          const result = await streamText({
   386→            model,
   387→            messages,
   388→            tools,
   389→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
   390→            onChunk: async ({ chunk }) => {
   391→              // Stream tool calls as they come in and capture their inputs
   392→              if (chunk.type === 'tool-call') {
   393→                const input = 'args' in chunk ? chunk.args : chunk.input;
   394→
   395→                // Log tool call for debugging
   396→                console.log('[Agent] Tool call initiated:', {
   397→                  toolName: chunk.toolName,
   398→                  toolCallId: chunk.toolCallId,
   399→                  input: JSON.stringify(input).slice(0, 500),
   400→                });
   401→
   402→                // Store tool call with input for later persistence
   403→                toolCallsMap.set(chunk.toolCallId, {
   404→                  toolCallId: chunk.toolCallId,
   405→                  toolName: chunk.toolName,
   406→                  args: input,
   407→                });
   408→                sendEvent('tool_call', {
   409→                  toolCallId: chunk.toolCallId,
   410→                  toolName: chunk.toolName,
   411→                  input,
   412→                });
   413→              }
   414→            },
   415→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
   416→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
   417→              // Capture tool calls from step finish (backup in case onChunk missed any)
   418→              if (toolCalls && Array.isArray(toolCalls)) {
   419→                for (const tc of toolCalls) {
   420→                  if (!toolCallsMap.has(tc.toolCallId)) {
   421→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
   422→                    const args =
   423→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
   424→                    toolCallsMap.set(tc.toolCallId, {
   425→                      toolCallId: tc.toolCallId,
   426→                      toolName: tc.toolName,
   427→                      args,
   428→                    });
   429→                  }
   430→                }
   431→              }
   432→
   433→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
   434→              if (toolResults && toolResults.length > 0) {
   435→                for (const tr of toolResults) {
   436→                  // Check if this is an error result (AI SDK wraps errors in the output)
   437→                  const isError =
   438→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
   439→
   440→                  // Log tool results for debugging
   441→                  if (isError) {
   442→                    console.error('[Agent] Tool execution failed:', {
   443→                      toolName: tr.toolName,
   444→                      toolCallId: tr.toolCallId,
   445→                      error: tr.output,
   446→                    });
   447→                  } else {
   448→                    console.log('[Agent] Tool execution success:', {
   449→                      toolName: tr.toolName,
   450→                      toolCallId: tr.toolCallId,
   451→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
   452→                    });
   453→                  }
   454→
   455→                  sendEvent('tool_result', {
   456→                    toolCallId: tr.toolCallId,
   457→                    output: tr.output,
   458→                    isError,
   459→                  });
   460→
   461→                  // Collect tool results to save after assistant message
   462→                  pendingToolResults.push({
   463→                    toolCallId: tr.toolCallId,
   464→                    toolName: tr.toolName,
   465→                    output: tr.output,
   466→                  });
   467→                }
   468→              }
   469→
   470→              // Track token usage
   471→              if (usage) {
   472→                inputTokens += usage.inputTokens ?? 0;
   473→                outputTokens += usage.outputTokens ?? 0;
   474→              }
   475→            },
   476→          });
   477→
   478→          // Stream text chunks
   479→          for await (const chunk of result.textStream) {
   480→            fullContent += chunk;
   481→            sendEvent('chunk', { type: 'text', text: chunk });
   482→          }
   483→
   484→          // Get final response data
   485→          const finalUsage = await result.usage;
   486→
   487→          // Convert tool calls map to array for storage
   488→          const allToolCalls = Array.from(toolCallsMap.values());
   489→
   490→          // Update token counts from final usage
   491→          if (finalUsage) {
   492→            inputTokens = finalUsage.inputTokens ?? inputTokens;
   493→            outputTokens = finalUsage.outputTokens ?? outputTokens;
   494→          }
   495→
   496→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
   497→          const assistantMessage = await prisma.message.create({
   498→            data: {
   499→              conversationId: conversation.id,
   500→              role: 'ASSISTANT',
   501→              content: fullContent,
   502→              // Cast to Prisma-compatible JSON type
   503→              toolCalls:
   504→                allToolCalls.length > 0
   505→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
   506→                  : Prisma.JsonNull,
   507→              inputTokens,
   508→              outputTokens,
   509→            },
   510→          });
   511→
   512→          // Now save TOOL messages (after assistant, for correct chronological order)
   513→          for (const tr of pendingToolResults) {
   514→            await prisma.message.create({
   515→              data: {
   516→                conversationId: conversation.id,
   517→                role: 'TOOL',
   518→                content: JSON.stringify(tr.output),
   519→                toolCallId: tr.toolCallId,
   520→                toolName: tr.toolName,
   521→                toolResult: tr.output as object,
   522→              },
   523→            });
   524→          }
   525→
   526→          // Update conversation timestamp
   527→          await prisma.conversation.update({
   528→            where: { id: conversation.id },
   529→            data: { updatedAt: new Date() },
   530→          });
