   532→          const executionTimeMs = Date.now() - startTime;
   533→
   534→          // Send token usage
   535→          sendEvent('tokens', {
   536→            inputTokens,
   537→            outputTokens,
   538→            totalTokens: inputTokens + outputTokens,
   539→          });
   540→
   541→          // Send completion event
   542→          sendEvent('complete', {
   543→            messageId: assistantMessage.id,
   544→            conversationId: conversation.id,
   545→            executionTimeMs,
   546→          });
   547→
   548→          // Track usage
   549→          if (authResult.userId) {
   550→            trackUsage({
   551→              apiKeyId: authResult.apiKeyId ?? undefined,
   552→              userId: authResult.userId,
   553→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
   554→              method: 'POST',
   555→              statusCode: 200,
   556→              latencyMs: executionTimeMs,
   557→              resourceType: 'agent',
   558→              resourceId: agentId,
   559→              tokensIn: inputTokens,
   560→              tokensOut: outputTokens,
   561→              model: agent.modelId,
   562→            });
   563→          }
   564→        } catch (error) {
   565→          // Log detailed error for debugging
   566→          console.error('[Agent] Conversation stream error:', {
   567→            error: error instanceof Error ? error.message : String(error),
   568→            stack: error instanceof Error ? error.stack : undefined,
   569→            agentId: agent.id,
   570→            conversationId: conversation.id,
   571→          });
   572→          sendEvent('error', {
   573→            message: error instanceof Error ? error.message : 'Unknown error',
   574→          });
   575→
   576→          // Track error
   577→          if (authResult.userId) {
   578→            trackUsage({
   579→              apiKeyId: authResult.apiKeyId ?? undefined,
   580→              userId: authResult.userId,
   581→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
   582→              method: 'POST',
   583→              statusCode: 500,
   584→              latencyMs: Date.now() - startTime,
   585→              resourceType: 'agent',
   586→              resourceId: agentId,
   587→              errorCode: 'STREAM_ERROR',
   588→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
   589→            });
   590→          }
   591→        } finally {
   592→          controller.close();
   593→        }
   594→      },
   595→    });
   596→
   597→    return new NextResponse(stream, {
   598→      headers: {
   599→        'Content-Type': 'text/event-stream',
   600→        'Cache-Control': 'no-cache',
   601→        Connection: 'keep-alive',
   602→      },
   603→    });
   604→  } catch (error) {
   605→    console.error('Failed to process message:', error);
   606→    return NextResponse.json(
   607→      {
   608→        success: false,
   609→        error: error instanceof Error ? error.message : 'Failed to process message',
   610→      },
   611→      { status: 500 }
   612→    );
   613→  }
   614→}
