   807→/**
   808→ * DELETE /api/agents/[id]/conversation/[conversationId]
   809→ * Delete a conversation
   810→ */
   811→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
   812→  const { id: agentId, conversationId } = await context.params;
   813→
   814→  try {
   815→    // Fetch agent by ID
   816→    const agent = await prisma.agent.findUnique({
   817→      where: { id: agentId },
   818→      select: { id: true },
   819→    });
   820→
   821→    if (!agent) {
   822→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
