   825→    // Delete conversation (messages cascade)
   826→    await prisma.conversation.deleteMany({
   827→      where: {
   828→        agentId: agent.id,
   829→        slug: conversationId,
   830→      },
   831→    });
   832→
   833→    return NextResponse.json({
   834→      success: true,
   835→      data: { deleted: true },
   836→    });
   837→  } catch (error) {
   838→    console.error('Failed to delete conversation:', error);
   839→    return NextResponse.json(
