    14→
    15→import { Prisma, prisma } from '@tpmjs/db';
    16→import type { AIProvider } from '@tpmjs/types/agent';
    17→import { SendMessageSchema } from '@tpmjs/types/agent';
    18→import type { LanguageModel, ModelMessage } from 'ai';
    19→import { type NextRequest, NextResponse } from 'next/server';
    20→import { decryptApiKey } from '@/lib/crypto/api-keys';
    21→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
    22→import { trackUsage } from '~/lib/api-keys/usage';
    23→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
    24→
    25→/**
    26→ * Rate limit for chat messages: 30 requests per minute
    27→ * This is stricter than default because chat involves expensive LLM calls
    28→ */
    29→const CHAT_RATE_LIMIT: RateLimitConfig = {
    30→  limit: 30,
    31→  windowSeconds: 60,
    32→};
    33→
    34→export const runtime = 'nodejs';
    35→export const dynamic = 'force-dynamic';
    36→export const maxDuration = 300; // 5 minutes for long agentic runs
    37→
    38→type RouteContext = {
    39→  params: Promise<{ username: string; agentSlug: string; conversationId: string }>;
    40→};
    41→
    42→/**
    43→ * Get AI provider SDK based on provider type
    44→ */
    45→async function getProviderModel(
    46→  provider: AIProvider,
    47→  modelId: string,
    48→  apiKey: string
    49→): Promise<LanguageModel> {
    50→  switch (provider) {
    51→    case 'OPENAI': {
    52→      const { createOpenAI } = await import('@ai-sdk/openai');
    53→      return createOpenAI({ apiKey })(modelId);
    54→    }
    55→    case 'ANTHROPIC': {
    56→      const { createAnthropic } = await import('@ai-sdk/anthropic');
    57→      return createAnthropic({ apiKey })(modelId);
    58→    }
    59→    case 'GOOGLE': {
    60→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
    61→      return createGoogleGenerativeAI({ apiKey })(modelId);
    62→    }
    63→    case 'GROQ': {
    64→      const { createGroq } = await import('@ai-sdk/groq');
    65→      return createGroq({ apiKey })(modelId);
    66→    }
    67→    case 'MISTRAL': {
    68→      const { createMistral } = await import('@ai-sdk/mistral');
    69→      return createMistral({ apiKey })(modelId);
    70→    }
    71→    default:
    72→      throw new Error(`Unsupported provider: ${provider}`);
    73→  }
    74→}
