   391→                for (const tr of toolResults) {
   392→                  // Check if this is an error result (AI SDK wraps errors in the output)
   393→                  const isError =
   394→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
   395→
   396→                  // Log tool results for debugging
   397→                  if (isError) {
   398→                    console.error('[Agent] Tool execution failed:', {
   399→                      toolName: tr.toolName,
   400→                      toolCallId: tr.toolCallId,
   401→                      error: tr.output,
   402→                    });
   403→                  } else {
   404→                    console.log('[Agent] Tool execution success:', {
   405→                      toolName: tr.toolName,
   406→                      toolCallId: tr.toolCallId,
   407→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
   408→                    });
   409→                  }
   410→
   411→                  sendEvent('tool_result', {
   412→                    toolCallId: tr.toolCallId,
   413→                    output: tr.output,
   414→                    isError,
   415→                  });
   416→
   417→                  // Collect tool results to save after assistant message
   418→                  pendingToolResults.push({
   419→                    toolCallId: tr.toolCallId,
   420→                    toolName: tr.toolName,
   421→                    output: tr.output,
   422→                  });
   423→                }
   424→              }
