   434→          // Stream text chunks
   435→          for await (const chunk of result.textStream) {
   436→            fullContent += chunk;
   437→            sendEvent('chunk', { type: 'text', text: chunk });
   438→          }
   439→
   440→          // Get final response data
   441→          const finalUsage = await result.usage;
   442→
   443→          // Convert tool calls map to array for storage
   444→          const allToolCalls = Array.from(toolCallsMap.values());
