   488→          const executionTimeMs = Date.now() - startTime;
   489→
   490→          // Send token usage
   491→          sendEvent('tokens', {
   492→            inputTokens,
   493→            outputTokens,
   494→            totalTokens: inputTokens + outputTokens,
   495→          });
