   512→              latencyMs: executionTimeMs,
   513→              resourceType: 'agent',
   514→              resourceId: agent.id,
   515→              tokensIn: inputTokens,
   516→              tokensOut: outputTokens,
   517→              model: agent.modelId,
   518→            });
   519→          }
   520→        } catch (error) {
   521→          // Log detailed error for debugging
   522→          console.error('[Agent] Conversation stream error:', {
   523→            error: error instanceof Error ? error.message : String(error),
   524→            stack: error instanceof Error ? error.stack : undefined,
