   549→        }
   550→      },
   551→    });
   552→
   553→    return new NextResponse(stream, {
   554→      headers: {
   555→        'Content-Type': 'text/event-stream',
   556→        'Cache-Control': 'no-cache',
   557→        Connection: 'keep-alive',
