   617→    if (!conversation) {
   618→      return NextResponse.json(
   619→        { success: false, error: 'Conversation not found' },
   620→        { status: 404 }
   621→      );
   622→    }
   623→
   624→    // For JSON format, return all messages with full details
   625→    if (format === 'json') {
   626→      const allMessages = await prisma.message.findMany({
   627→        where: { conversationId: conversation.id },
   628→        orderBy: { createdAt: 'asc' },
   629→      });
   630→
   631→      const response = {
   632→        _meta: {
   633→          exportedAt: new Date().toISOString(),
   634→          format: 'tpmjs-conversation-log',
   635→          version: '1.0',
   636→        },
   637→        agent: {
   638→          id: agent.id,
   639→          uid: agent.uid,
   640→          name: agent.name,
   641→          provider: agent.provider,
   642→          modelId: agent.modelId,
   643→          executorType: agent.executorType,
   644→          executorConfig: agent.executorConfig,
   645→        },
   646→        conversation: {
   647→          id: conversation.id,
   648→          slug: conversation.slug,
   649→          title: conversation.title,
   650→          createdAt: conversation.createdAt,
   651→          updatedAt: conversation.updatedAt,
   652→          messageCount: allMessages.length,
   653→        },
   654→        messages: allMessages.map((m) => ({
   655→          id: m.id,
   656→          role: m.role,
   657→          content: m.content,
   658→          toolCalls: m.toolCalls,
   659→          toolCallId: m.toolCallId,
   660→          toolName: m.toolName,
   661→          toolResult: m.toolResult,
   662→          inputTokens: m.inputTokens,
   663→          outputTokens: m.outputTokens,
   664→          createdAt: m.createdAt,
   665→        })),
   666→        stats: {
   667→          totalMessages: allMessages.length,
   668→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
   669→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
   670→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
   671→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
   672→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
   673→        },
   674→      };
   675→
   676→      // Return pretty-printed JSON with proper content type
   677→      return new NextResponse(JSON.stringify(response, null, 2), {
   678→        headers: {
   679→          'Content-Type': 'application/json',
   680→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
   681→        },
   682→      });
   683→    }
   684→
   685→    // Standard paginated response
   686→    const whereClause: {
   687→      conversationId: string;
   688→      createdAt?: { lt?: Date; gt?: Date };
   689→    } = { conversationId: conversation.id };
   690→
   691→    if (before) {
   692→      whereClause.createdAt = { lt: new Date(before) };
   693→    } else if (after) {
   694→      whereClause.createdAt = { gt: new Date(after) };
   695→    }
   696→
   697→    // Determine fetch order:
   698→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
   699→    // - "after": Fetch asc (oldest first) to get messages after the cursor
   700→    const shouldFetchDesc = !after;
   701→
   702→    // Fetch messages
   703→    const messages = await prisma.message.findMany({
   704→      where: whereClause,
   705→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
   706→      take: limit + 1,
   707→    });
