   717→    const mappedMessages = paginatedMessages.map((m) => ({
   718→      id: m.id,
   719→      role: m.role,
   720→      content: m.content,
   721→      toolCalls: m.toolCalls,
   722→      toolCallId: m.toolCallId,
   723→      toolName: m.toolName,
   724→      toolResult: m.toolResult,
   725→      inputTokens: m.inputTokens,
