   734→        slug: conversation.slug,
   735→        title: conversation.title,
   736→        createdAt: conversation.createdAt,
   737→        updatedAt: conversation.updatedAt,
   738→        messages: mappedMessages,
   739→      },
   740→      pagination: {
   741→        limit,
   742→        hasMore,
   743→        ...(before && { before }),
   744→        ...(after && { after }),
   745→      },
   746→    });
   747→  } catch (error) {
   748→    console.error('Failed to fetch conversation:', error);
   749→    return NextResponse.json(
   750→      { success: false, error: 'Failed to fetch conversation' },
   751→      { status: 500 }
   752→    );
   753→  }
   754→}
