   245→  private async request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
   246→    const url = `${this.baseUrl}${endpoint}`;
   247→    const headers: Record<string, string> = {
   248→      'Content-Type': 'application/json',
   249→      ...(options.headers as Record<string, string>),
   250→    };
