   257→    const timeoutId = setTimeout(() => controller.abort(), this.timeout);
   258→
   259→    try {
   260→      const response = await fetch(url, {
   261→        ...options,
   262→        headers,
   263→        signal: controller.signal,
   264→      });
   265→
   266→      const data = (await response.json()) as T & { message?: string; error?: string };
   267→
   268→      if (!response.ok) {
