     5→export default class CollectionAdd extends Command {
     6→  static description = 'Add tools to a collection';
     7→
     8→  static examples = [
     9→    '<%= config.bin %> <%= command.id %> my-collection tool-id-1',
    10→    '<%= config.bin %> <%= command.id %> my-collection tool-id-1 tool-id-2 tool-id-3',
    11→  ];
    12→
    13→  static strict = false; // Allow variable number of arguments
    14→
    15→  static flags = {
    16→    json: Flags.boolean({
    17→      description: 'Output in JSON format',
    18→      default: false,
    19→    }),
    20→    verbose: Flags.boolean({
