   401→          isError: content.isError,
   402→        },
   403→      };
   404→    }
   405→
   406→    return {
   407→      jsonrpc: '2.0',
   408→      id: requestId,
   409→      result: {
   410→        content: [
   411→          {
   412→            type: 'text',
   413→            text:
   414→              typeof result.result === 'string'
   415→                ? result.result
   416→                : JSON.stringify(result.result, null, 2),
   417→          },
   418→        ],
   419→      },
   420→    };
   421→  } catch (error) {
   422→    console.error('[MCP bridge tool call] Error:', error);
   423→    return {
   424→      jsonrpc: '2.0',
   425→      id: requestId,
   426→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
   427→    };
   428→  }
   429→}
