   616→/**
   617→ * GET /api/agents/[id]/conversation/[conversationId]
   618→ * Retrieve conversation history with pagination
   619→ *
   620→ * Query params:
   621→ * - limit: Max messages to return (default: 50, max: 100)
   622→ * - before: Fetch messages created before this ISO timestamp (for loading older messages)
   623→ * - after: Fetch messages created after this ISO timestamp (for loading newer messages)
   624→ * - format: 'json' for full debug view (no pagination, includes agent info)
   625→ *
   626→ * Default behavior (no before/after): Returns the most recent messages
   627→ * With before: Returns messages older than the timestamp (for scrolling up)
   628→ * With after: Returns messages newer than the timestamp (for refreshing)
   629→ */
   630→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
   631→  const { id: agentId, conversationId } = await context.params;
   632→  const { searchParams } = new URL(request.url);
   633→
   634→  const format = searchParams.get('format');
   635→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
   636→  const before = searchParams.get('before');
   637→  const after = searchParams.get('after');
   638→
   639→  try {
   640→    // Fetch agent by ID with more details for JSON format
   641→    const agent = await prisma.agent.findUnique({
   642→      where: { id: agentId },
   643→      select: {
   644→        id: true,
   645→        uid: true,
   646→        name: true,
   647→        provider: true,
   648→        modelId: true,
   649→        executorType: true,
   650→        executorConfig: true,
   651→      },
   652→    });
   653→
   654→    if (!agent) {
   655→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
   656→    }
   657→
   658→    // Fetch conversation
   659→    const conversation = await prisma.conversation.findUnique({
   660→      where: {
   661→        agentId_slug: {
   662→          agentId: agent.id,
   663→          slug: conversationId,
   664→        },
   665→      },
   666→    });
   667→
   668→    if (!conversation) {
   669→      return NextResponse.json(
   670→        { success: false, error: 'Conversation not found' },
   671→        { status: 404 }
   672→      );
   673→    }
   674→
   675→    // For JSON format, return all messages with full details
   676→    if (format === 'json') {
   677→      const allMessages = await prisma.message.findMany({
   678→        where: { conversationId: conversation.id },
   679→        orderBy: { createdAt: 'asc' },
   680→      });
   681→
   682→      const response = {
   683→        _meta: {
   684→          exportedAt: new Date().toISOString(),
   685→          format: 'tpmjs-conversation-log',
   686→          version: '1.0',
   687→        },
   688→        agent: {
   689→          id: agent.id,
   690→          uid: agent.uid,
   691→          name: agent.name,
   692→          provider: agent.provider,
   693→          modelId: agent.modelId,
   694→          executorType: agent.executorType,
   695→          executorConfig: agent.executorConfig,
   696→        },
   697→        conversation: {
   698→          id: conversation.id,
   699→          slug: conversation.slug,
   700→          title: conversation.title,
   701→          createdAt: conversation.createdAt,
   702→          updatedAt: conversation.updatedAt,
   703→          messageCount: allMessages.length,
   704→        },
   705→        messages: allMessages.map((m) => ({
   706→          id: m.id,
   707→          role: m.role,
   708→          content: m.content,
   709→          toolCalls: m.toolCalls,
   710→          toolCallId: m.toolCallId,
   711→          toolName: m.toolName,
   712→          toolResult: m.toolResult,
   713→          inputTokens: m.inputTokens,
   714→          outputTokens: m.outputTokens,
   715→          createdAt: m.createdAt,
   716→        })),
   717→        stats: {
   718→          totalMessages: allMessages.length,
   719→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
   720→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
   721→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
   722→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
   723→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
   724→        },
   725→      };
   726→
   727→      // Return pretty-printed JSON with proper content type
   728→      return new NextResponse(JSON.stringify(response, null, 2), {
   729→        headers: {
   730→          'Content-Type': 'application/json',
   731→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
   732→        },
   733→      });
   734→    }
   735→
   736→    // Standard paginated response
   737→    const whereClause: {
   738→      conversationId: string;
   739→      createdAt?: { lt?: Date; gt?: Date };
   740→    } = { conversationId: conversation.id };
   741→
   742→    if (before) {
   743→      whereClause.createdAt = { lt: new Date(before) };
   744→    } else if (after) {
   745→      whereClause.createdAt = { gt: new Date(after) };
   746→    }
   747→
   748→    // Determine fetch order:
   749→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
   750→    // - "after": Fetch asc (oldest first) to get messages after the cursor
   751→    const shouldFetchDesc = !after;
   752→
   753→    // Fetch messages
   754→    const messages = await prisma.message.findMany({
   755→      where: whereClause,
   756→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
   757→      take: limit + 1,
   758→    });
   759→
   760→    const hasMore = messages.length > limit;
   761→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
   762→
   763→    // Reverse if we fetched in desc order to maintain chronological order
   764→    if (shouldFetchDesc) {
   765→      paginatedMessages = paginatedMessages.reverse();
   766→    }
   767→
   768→    const mappedMessages = paginatedMessages.map((m) => ({
   769→      id: m.id,
   770→      role: m.role,
   771→      content: m.content,
   772→      toolCalls: m.toolCalls,
   773→      toolCallId: m.toolCallId,
   774→      toolName: m.toolName,
   775→      toolResult: m.toolResult,
   776→      inputTokens: m.inputTokens,
   777→      outputTokens: m.outputTokens,
   778→      createdAt: m.createdAt,
   779→    }));
   780→
   781→    return NextResponse.json({
   782→      success: true,
   783→      data: {
   784→        id: conversation.id,
   785→        slug: conversation.slug,
   786→        title: conversation.title,
   787→        createdAt: conversation.createdAt,
   788→        updatedAt: conversation.updatedAt,
   789→        messages: mappedMessages,
   790→      },
   791→      pagination: {
   792→        limit,
   793→        hasMore,
   794→        ...(before && { before }),
   795→        ...(after && { after }),
   796→      },
   797→    });
   798→  } catch (error) {
   799→    console.error('Failed to fetch conversation:', error);
   800→    return NextResponse.json(
   801→      { success: false, error: 'Failed to fetch conversation' },
   802→      { status: 500 }
   803→    );
   804→  }
   805→}
