    81→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
    82→  const startTime = Date.now();
    83→
    84→  // Authenticate request (supports both session and API key)
    85→  const authResult = await authenticateRequest();
    86→
    87→  if (!authResult.authenticated) {
    88→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    89→  }
    90→
    91→  // Check scope for API key auth
    92→  if (authResult.authenticated && !authResult.isSessionAuth) {
    93→    if (!hasScope(authResult, 'agent:chat')) {
    94→      return NextResponse.json(
    95→        { error: 'API key does not have agent:chat scope' },
    96→        { status: 403 }
    97→      );
    98→    }
    99→  }
   100→
   101→  // Check rate limit (after auth so we can track by user if needed)
   102→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
   103→  if (rateLimitResponse) {
   104→    return rateLimitResponse;
   105→  }
   106→
   107→  const { username, agentSlug, conversationId } = await context.params;
   108→
   109→  try {
   110→    const body = await request.json();
   111→    const parsed = SendMessageSchema.safeParse(body);
   112→    if (!parsed.success) {
   113→      return NextResponse.json(
   114→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
   115→        { status: 400 }
   116→      );
   117→    }
   118→
   119→    // Fetch agent by username and slug with all tool relations
   120→    const { fetchAgentByUsernameAndUidWithTools, buildAgentTools } = await import(
   121→      '@/lib/agents/build-tools'
   122→    );
   123→    const agent = await fetchAgentByUsernameAndUidWithTools(username, agentSlug);
   124→
   125→    if (!agent) {
   126→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
   127→    }
   128→
   129→    // Owner-only enforcement: Only the agent owner can chat with the agent
   130→    if (authResult.userId !== agent.userId) {
   131→      return NextResponse.json(
   132→        {
   133→          success: false,
   134→          error:
   135→            'Fork this agent to use it. Only the agent owner can chat with agents. ' +
   136→            'Visit the agent page to fork it to your account.',
   137→        },
   138→        { status: 403 }
   139→      );
   140→    }
   141→
   142→    // Map provider to expected key name format
   143→    const providerKeyNames: Record<string, string> = {
   144→      OPENAI: 'OPENAI_API_KEY',
   145→      ANTHROPIC: 'ANTHROPIC_API_KEY',
   146→      GOOGLE: 'GOOGLE_API_KEY',
   147→      GROQ: 'GROQ_API_KEY',
   148→      MISTRAL: 'MISTRAL_API_KEY',
   149→    };
   150→    const keyName = providerKeyNames[agent.provider];
   151→
   152→    if (!keyName) {
   153→      return NextResponse.json(
   154→        { success: false, error: `Unsupported provider: ${agent.provider}` },
   155→        { status: 400 }
   156→      );
   157→    }
   158→
   159→    // Get user's API key for this provider
   160→    const userApiKey = await prisma.userApiKey.findUnique({
   161→      where: {
   162→        userId_keyName: {
   163→          userId: agent.userId,
   164→          keyName,
   165→        },
   166→      },
   167→    });
   168→
   169→    if (!userApiKey) {
   170→      return NextResponse.json(
   171→        {
   172→          success: false,
   173→          error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
   174→        },
   175→        { status: 400 }
   176→      );
   177→    }
   178→
   179→    // Decrypt the API key
   180→    const apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
   181→
   182→    // Get or create conversation
   183→    let conversation = await prisma.conversation.findUnique({
   184→      where: {
   185→        agentId_slug: {
   186→          agentId: agent.id,
   187→          slug: conversationId,
   188→        },
   189→      },
   190→    });
   191→
   192→    if (!conversation) {
   193→      conversation = await prisma.conversation.create({
   194→        data: {
   195→          agentId: agent.id,
   196→          slug: conversationId,
   197→          title: parsed.data.message.slice(0, 100),
   198→        },
   199→      });
   200→    }
   201→
   202→    // Fetch recent messages for context
   203→    const recentMessages = await prisma.message.findMany({
   204→      where: { conversationId: conversation.id },
   205→      orderBy: { createdAt: 'desc' },
   206→      take: agent.maxMessagesInContext,
   207→    });
   208→
   209→    // Reverse to get chronological order
   210→    recentMessages.reverse();
   211→
   212→    // Save user message
   213→    await prisma.message.create({
   214→      data: {
   215→        conversationId: conversation.id,
   216→        role: 'USER',
   217→        content: parsed.data.message,
   218→      },
   219→    });
   220→
   221→    // Build AI SDK messages from conversation history
   222→    const { streamText, stepCountIs } = await import('ai');
   223→
   224→    const messages: ModelMessage[] = [];
   225→
   226→    // Add system prompt if defined
   227→    if (agent.systemPrompt) {
   228→      messages.push({
   229→        role: 'system',
   230→        content: agent.systemPrompt,
   231→      });
   232→    }
   233→
   234→    // Build a set of tool call IDs that have corresponding tool results
   235→    // This is needed because AI SDK requires every tool call to have a matching tool result
   236→    const toolResultIds = new Set(
   237→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
   238→    );
   239→
   240→    // Add conversation history - properly format for AI SDK
   241→    for (const msg of recentMessages) {
   242→      if (msg.role === 'USER') {
   243→        messages.push({ role: 'user', content: msg.content });
   244→      } else if (msg.role === 'ASSISTANT') {
   245→        // For assistant messages with tool calls, include ToolCallParts in content
   246→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
   247→          // Only include tool calls that have matching tool results
   248→          // AI SDK fails if there's a tool call without a corresponding tool result
   249→          const validToolCalls = (
   250→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
   251→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
   252→
   253→          if (validToolCalls.length > 0) {
   254→            const toolCallParts = validToolCalls.map((tc) => ({
   255→              type: 'tool-call' as const,
   256→              toolCallId: tc.toolCallId,
   257→              toolName: tc.toolName,
   258→              input: tc.args,
   259→            }));
   260→            // Content includes text (if any) plus tool call parts
   261→            const content: Array<
   262→              | { type: 'text'; text: string }
   263→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
   264→            > = [];
   265→            if (msg.content) {
   266→              content.push({ type: 'text', text: msg.content });
   267→            }
   268→            content.push(...toolCallParts);
   269→            messages.push({
   270→              role: 'assistant',
   271→              content,
   272→            });
   273→          } else {
   274→            // All tool calls are missing results, just include text content
   275→            messages.push({
   276→              role: 'assistant',
   277→              content: msg.content || '',
   278→            });
   279→          }
   280→        } else {
   281→          messages.push({
   282→            role: 'assistant',
   283→            content: msg.content,
   284→          });
   285→        }
   286→      } else if (msg.role === 'TOOL') {
   287→        // Tool results use the 'tool' role with content array
   288→        messages.push({
   289→          role: 'tool',
   290→          content: [
   291→            {
   292→              type: 'tool-result' as const,
   293→              toolCallId: msg.toolCallId || '',
   294→              toolName: msg.toolName || '',
   295→              output: {
   296→                type: 'json' as const,
   297→                value: msg.toolResult,
   298→              },
   299→            },
   300→          ],
   301→        });
   302→      }
   303→    }
   304→
   305→    // Add new user message
   306→    messages.push({ role: 'user', content: parsed.data.message });
   307→
   308→    // Build tools from agent configuration
   309→    const tools = buildAgentTools(agent);
   310→
   311→    // Get the provider model
   312→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
   313→
   314→    // Create SSE stream
   315→    const stream = new ReadableStream({
   316→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
   317→      async start(controller) {
   318→        const encoder = new TextEncoder();
   319→
   320→        const sendEvent = (event: string, data: unknown) => {
   321→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
   322→          controller.enqueue(encoder.encode(message));
   323→        };
   324→
   325→        try {
   326→          const startTime = Date.now();
   327→          let fullContent = '';
   328→          // Accumulate tool calls with their input args
   329→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
   330→            new Map();
   331→          // Collect tool results to save AFTER assistant message (for correct chronological order)
   332→          const pendingToolResults: Array<{
   333→            toolCallId: string;
   334→            toolName: string;
   335→            output: unknown;
   336→          }> = [];
   337→          let inputTokens = 0;
   338→          let outputTokens = 0;
   339→
   340→          // Stream the response with agentic loop control
   341→          const result = await streamText({
   342→            model,
   343→            messages,
   344→            tools,
   345→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
   346→            onChunk: async ({ chunk }) => {
   347→              // Stream tool calls as they come in and capture their inputs
   348→              if (chunk.type === 'tool-call') {
   349→                const input = 'args' in chunk ? chunk.args : chunk.input;
   350→
   351→                // Log tool call for debugging
   352→                console.log('[Agent] Tool call initiated:', {
   353→                  toolName: chunk.toolName,
   354→                  toolCallId: chunk.toolCallId,
   355→                  input: JSON.stringify(input).slice(0, 500),
   356→                });
   357→
   358→                // Store tool call with input for later persistence
   359→                toolCallsMap.set(chunk.toolCallId, {
   360→                  toolCallId: chunk.toolCallId,
   361→                  toolName: chunk.toolName,
   362→                  args: input,
   363→                });
   364→                sendEvent('tool_call', {
   365→                  toolCallId: chunk.toolCallId,
   366→                  toolName: chunk.toolName,
   367→                  input,
   368→                });
   369→              }
   370→            },
   371→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
   372→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
   373→              // Capture tool calls from step finish (backup in case onChunk missed any)
   374→              if (toolCalls && Array.isArray(toolCalls)) {
   375→                for (const tc of toolCalls) {
   376→                  if (!toolCallsMap.has(tc.toolCallId)) {
   377→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
   378→                    const args =
   379→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
   380→                    toolCallsMap.set(tc.toolCallId, {
   381→                      toolCallId: tc.toolCallId,
   382→                      toolName: tc.toolName,
   383→                      args,
   384→                    });
   385→                  }
   386→                }
   387→              }
   388→
   389→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
   390→              if (toolResults && toolResults.length > 0) {
   391→                for (const tr of toolResults) {
   392→                  // Check if this is an error result (AI SDK wraps errors in the output)
   393→                  const isError =
