   467→
   468→          // Now save TOOL messages (after assistant, for correct chronological order)
   469→          for (const tr of pendingToolResults) {
   470→            await prisma.message.create({
   471→              data: {
   472→                conversationId: conversation.id,
   473→                role: 'TOOL',
   474→                content: JSON.stringify(tr.output),
