   476→                toolName: tr.toolName,
   477→                toolResult: tr.output as object,
   478→              },
   479→            });
   480→          }
   481→
   482→          // Update conversation timestamp
   483→          await prisma.conversation.update({
   484→            where: { id: conversation.id },
   485→            data: { updatedAt: new Date() },
   486→          });
   487→
   488→          const executionTimeMs = Date.now() - startTime;
   489→
   490→          // Send token usage
   491→          sendEvent('tokens', {
