   669→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
   670→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
   671→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
